651	pub fn write_sled_from_wg(peer_pubkey: &str) -> std::io::Result<()> {
652	    let wireguard_pubkey = decode_wg_pubkey(peer_pubkey);
653	    let mutation_index = MUTATION_INDEX.fetch_add(1, Ordering::Relaxed);
654	
655	    // Per-session WireGuard source port binds the footprint to the session
656	    // network context (accountability loop); then the canonical Strike/Etch.
657	    let source_port = peer_source_port(peer_pubkey);
658	    let hashed_footprint = etch_footprint(&wireguard_pubkey, mutation_index, source_port);
659	
660	    // Trace propagation: reuse existing UUID if present, else mint v4
661	    let trace_id: [u8; 16] = if let Ok(existing) = env::var("GB_TRACE_ID") {
662	        hex::decode(existing.trim())
663	            .ok()
664	            .and_then(|v| v.try_into().ok())
