76	/// Example:  `sch.network.plugin-schema.resolve@v1`
77	#[derive(Debug, Clone, PartialEq, Eq)]
78	pub struct SubidTaxonomy {
79	    pub category: SubidCategory,
80	    pub component_type: String,
81	    pub subject: String,
82	    pub verb: String,
83	    pub facet: Option<String>,
84	    pub version: u8,
85	}
86	
87	impl SubidTaxonomy {
88	    /// Parse a subid string into its taxonomy components.
89	    pub fn parse(s: &str) -> Result<Self, String> {
90	        // Strip optional @vN suffix
91	        let (body, version) = if let Some(at) = s.rfind('@') {
92	            let ver_str = &s[at + 1..];
93	            let ver: u8 = ver_str
94	                .strip_prefix('v')
95	                .and_then(|n| n.parse().ok())
96	                .ok_or_else(|| format!("invalid version suffix: {ver_str}"))?;
97	            (&s[..at], ver)
98	        } else {
99	            (s, 0)
100	        };
101	
102	        let mut parts = body.splitn(5, '.');
103	        let cat_str = parts.next().ok_or("missing category")?;
104	        let category =
105	            SubidCategory::parse(cat_str).ok_or_else(|| format!("unknown category: {cat_str}"))?;
106	        let component_type = parts.next().ok_or("missing component-type")?.to_string();
107	        let subject = parts.next().ok_or("missing subject")?.to_string();
108	        let verb = parts.next().ok_or("missing verb")?.to_string();
109	        let facet = parts.next().map(str::to_string);
110	
111	        // Basic segment validation: lowercase ASCII + hyphens only
112	        for seg in [&component_type, &subject, &verb] {
113	            if seg.is_empty()
114	                || !seg
115	                    .chars()
116	                    .all(|c| c.is_ascii_lowercase() || c == '-' || c.is_ascii_digit())
117	            {
118	                return Err(format!(
119	                    "invalid segment '{seg}': must be lowercase ascii/digits/hyphens"
120	                ));
121	            }
122	        }
123	
124	        Ok(Self {
125	            category,
126	            component_type,
127	            subject,
128	            verb,
129	            facet,
130	            version,
131	        })
132	    }
133	
134	    /// Reconstruct the canonical subid string.
135	    pub fn canonical(&self) -> String {
136	        let mut s = format!(
137	            "{}.{}.{}.{}",
138	            self.category.as_str(),
139	            self.component_type,
140	            self.subject,
141	            self.verb,
142	        );
143	        if let Some(f) = &self.facet {
144	            s.push('.');
145	            s.push_str(f);
146	        }
147	        if self.version > 0 {
148	            s.push_str(&format!("@v{}", self.version));
149	        }
150	        s
151	    }
152	}
