const DEFAULT_QDRANT_ENDPOINT: &str = "http://127.0.0.1:6334";
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct KnowledgeState {
    pub status: String,
    pub stores: Value,
    pub embedding: Value,
    pub config: Value,
