service MqService {
  rpc Publish(PublishRequest) returns (PublishResponse);
  rpc Subscribe(SubscribeRequest) returns (stream MqMessage);
  rpc ListTopics(ListTopicsRequest) returns (ListTopicsResponse);
}

--- the messages MqService uses ---
message PublishRequest {
  string topic = 1;
  bytes payload = 2;
  uint32 qos = 3;
  bool retain = 4;
}

message PublishResponse { bool success = 1; }
message SubscribeRequest { repeated string topics = 1; uint32 qos = 2; }
message MqMessage { string topic = 1; bytes payload = 2; uint64 timestamp = 3; }
message ListTopicsRequest {}
